/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchList = async function () {
    /* sdd-asis-lifecycle:begin fn_searchList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('cal_searchBeginDd').getValue()> $c.util.getComponent('cal_searchEndDd').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    frm.action = "/submission/searchDisclosureDocument.do?method=searchOtherSystemDocument";
    await scwin.tx_fn_searchList();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.deleteSearchListReq
 * @author Inswave
 * @date 2026. 09. 29
 * @param applNo
 * @returns
 * @hidden N
*/
scwin.deleteSearchListReq = async function (applNo) {
    /* sdd-asis-lifecycle:begin fn_delete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await $c.win.confirm('삭제하시겠습니까?')) {
        (document.searchForm || { elements: [] }).action = "/submission/searchDisclosureDocument.do?method=removeOtherSystemDocument";
        $c.util.getComponent('dma_searchListReq').set('applNo', applNo);
        await scwin.tx_fn_delete();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goSubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goSubmit = async function () {
    /* sdd-asis-lifecycle:begin fn_goSubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let chksize = 0;
    try {
        chksize = $c.util.getComponent('ipt_applNoArr').length;
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil00500' }); }
    let isChecked = false;
    let chkTrueCnt = 0;
    if (chksize == null || chksize == 1) {
        if ((String($c.util.getComponent('ipt_applNoArr').getValue() || "") !== "")) {
            isChecked = true;
            chkTrueCnt++;
        }
    } else {
        for (scwin.i = 0; scwin.i < chksize; scwin.i++) {
            if ($c.util.getComponent('ipt_applNoArr')[scwin.i].checked) {
                isChecked = true;
                chkTrueCnt++;
            }
        }
    }
    if (!isChecked) {
        await $c.win.alert('제출할 공시를 하나 이상 체크하십시요');
        return;
    }
    if (!await $c.win.confirm('해당 공시는 오후 8시에 일괄 배포됩니다.\n선택한 공시를 예약배포 하시겠습니까?\n* 오후 8시가 경과 하였을 경우 즉시 배포됩니다.')) {
        return;
    }
    if (!await $c.win.confirm(chkTrueCnt + '개의 타시스템 공시를 제출하시겠습니까?')) {
        return;
    }
    (document.searchForm || { elements: [] }).action = '/submission/othersubmit.do?method=executeOtherSystemDocument';
    await scwin.tx_fn_goSubmit();
    /* sdd-asis-lifecycle:end */
};


